static Graph g;
static long long dist[MAX_V];
g.init(3);
assert(g.addEdge(0,1,2) && g.addEdge(0,2,5) && g.addEdge(2,1,-10));
assert(dijkstra(g,3,0,dist) && dist[0]==0 && dist[1]==-5 && dist[2]==5);
mt19937 rng(20260922);
for(int tc=0;tc<300;++tc) {
    int n=1+rng()%10,s=rng()%n;
    g.init(n);
    vector<array<long long,3>> edges;
    for(int e=0;e<n*n;++e) if(rng()%2) {
        int u=rng()%n,v=rng()%n; long long w=static_cast<long long>(rng()%1000000001ULL);
        assert(g.addEdge(u,v,w)); edges.push_back({u,v,w});
    }
    vector<long long> best(n,INF); best[s]=0;
    for(int step=0;step<n-1;++step) {
        auto after=best;
        for(auto& e:edges) if(best[e[0]]!=INF) after[e[1]]=min(after[e[1]],best[e[0]]+e[2]);
        best.swap(after);
    }
    assert(dijkstra(g,n,s,dist));
    for(int i=0;i<n;++i) assert(dist[i]==best[i]);
}
g.init(4);
assert(g.addEdge(0,1,7) && g.addEdge(0,1,0) && g.addEdge(0,2,9) && g.addEdge(1,2,0));
assert(dijkstra(g,4,0,dist) && dist[0]==0 && dist[1]==0 && dist[2]==0 && dist[3]==INF);
assert(!dijkstra(g,4,4,dist) && !dijkstra(g,0,0,dist));
